def has_unique_digits(year):
    str_year = str(year)
    length = len(str_year)
    for i in range(length):
        for j in range(i + 1, length):
            if str_year[i] == str_year[j]:
                return False
    return True

def next_unique_year(current_year):
    next_year = current_year + 1
    while True:
        if has_unique_digits(next_year):
            return next_year
        next_year += 1

def count_usable_ingredients(T, input_lines):
    count = 0  
    for line in input_lines:
        RA_parts = line.split()  
        if len(RA_parts) != 2:
            continue 
        R = int(RA_parts[0]) 
        A = int(RA_parts[1]) 
        if A >= R:
            count += 1
    return count

def find_perfect_squares(N):
    perfect_squares = []
    for i in range(1, N + 1):
        root = 1
        while root * root < i:
            root += 1
        if root * root == i:
            perfect_squares.append(i)
    return perfect_squares

def count_successful_villagers(N):
    successful_villagers = 0
    for i in range(1, N + 1):
        fruits = i
        layers = 0
        while fruits > 0 and layers < 10:
            layers += 1
            fruits -= layers
        if fruits == 0 and layers <= 10:
            successful_villagers += 1
    return successful_villagers

def count_hurdles(N, K, heights):
    count = 0
    for h in heights:
        if h <= K:
            count += 1
    return count

def passing_rounds(F, limits):
    rounds = 0
    while True:
        for i in range(F):
            if limits[i] == 0:
                return rounds
            limits[i] -= 1
        rounds += 1

