N = int(input())
T = int(input())

scores = [int(input()) for i in range(N)]

def is_valid(score):
    return score >= T

def grade(score):
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

valid_scores = filter(is_valid, scores)
grades = list(map(grade, valid_scores))

print(grades)

N = int(input())

books = [input().strip().split(', ') for i in range(N)]

def is_available(book):
    return book[1] == 'available'

def to_uppercase(book):
    return book[0].upper()

available_books = filter(is_available, books)
uppercase_titles = list(map(to_uppercase, available_books))

print(uppercase_titles)

from functools import reduce

N = int(input())
M = int(input())

step_counts = [int(input()) for i in range(N)]

def is_valid(step_count):
    return step_count >= M

def categorize(step_count):
    if step_count >= 10000:
        return 'Active'
    elif step_count >= 5000:
        return 'Moderately Active'
    else:
        return 'Sedentary'

def sum_active_steps(total, step_count):
    if step_count >= 10000:
        return total + step_count
    return total

valid_steps = filter(is_valid, step_counts)
activity_levels = list(map(categorize, valid_steps))
total_active_steps = reduce(sum_active_steps, filter(is_valid, step_counts), 0)

print(activity_levels, total_active_steps)

